def forward(groups):
    sp1, less_than, minutes, seconds, sec_value, sp2 = groups
    if less_than == '<':
        total_seconds = 0
    elif minutes is not None:
        total_seconds = int(minutes) * 60 + int(seconds)
    else:
        total_seconds = int(sec_value)
    layout = [len(sp1), 1 if less_than else 0, int(bool(minutes)), len(sp2 or '')]
    return {'stored': [total_seconds], 'layout': layout}

def inverse(record):
    seconds = int(record['stored'][0])
    layout = record.get('layout', [])
    sp1_len, is_less_than, has_minutes, sp2_len = layout
    sp1 = ' ' * sp1_len
    sp2 = ' ' * sp2_len
    if is_less_than:
        return f'lifetime{sp1}<1{sp2}sec'
    elif has_minutes:
        minutes = seconds // 60
        sec = seconds % 60
        return f'lifetime{sp1}{str(minutes).zfill(2)}:{str(sec).zfill(2)}'
    else:
        return f'lifetime{sp1}{seconds}{sp2}sec'
